#include "stdlib/lapack/base/dgbtf2.h"
#include "stdlib/lapack/base/shared.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/time.h>

#define ITERATIONS 200
#define REPEATS 2

/**
* Returns a clock time in seconds.
*
* @return clock time
*/
static double tic( void ) {
	struct timeval now;
	gettimeofday( &now, NULL );
	return (double)now.tv_sec + (double)now.tv_usec/1.0e6;
}

/**
* Resets and factors a bounded band matrix, then validates its outputs.
*
* @param N         column count
* @param tall      whether to add two rows
* @param ndarray   whether to use explicit column-major indexing
* @param singular  whether the first column is zero
* @return          elapsed seconds or -1 on failure
*/
static double benchmark( const LAPACK_INT N, const int tall, const int ndarray, const int singular ) {
	double *original;
	double *AB;
	LAPACK_INT *PIV;
	LAPACK_INT M;
	LAPACK_INT r;
	LAPACK_INT c;
	LAPACK_INT expectedInfo;
	LAPACK_INT info;
	LAPACK_INT i;
	LAPACK_INT j;
	double elapsed;
	double t;
	int k;

	M = tall ? N+2 : N;
	r = ndarray ? 1 : N;
	c = ndarray ? 4 : 1;
	original = (double *)malloc( (size_t)(4*N) * sizeof( double ) );
	AB = (double *)malloc( (size_t)(4*N) * sizeof( double ) );
	PIV = (LAPACK_INT *)malloc( (size_t)N * sizeof( LAPACK_INT ) );
	if ( original == NULL || AB == NULL || PIV == NULL ) {
		fprintf( stderr, "Error allocating bounded benchmark buffers.\n" );
		free( original );
		free( AB );
		free( PIV );
		return -1.0;
	}
	for ( i = 0; i < 4*N; i++ ) {
		original[ i ] = 999.0;
	}
	for ( j = 0; j < N; j++ ) {
		PIV[ j ] = -99;
		original[ (2*r)+(j*c) ] = ( singular && j == 0 ) ? 0.0 : (double)N+4.0;
		if ( j > 0 ) {
			original[ r+(j*c) ] = 0.5;
		}
		if ( j+1 < M ) {
			original[ (3*r)+(j*c) ] = ( singular && j == 0 ) ? 0.0 : 0.25;
		}
	}
	expectedInfo = singular ? 1 : 0;
	info = -9;
	t = tic();
	for ( k = 0; k < ITERATIONS; k++ ) {
		// Include resetting the compact input in the measured workload:
		memcpy( AB, original, (size_t)(4*N) * sizeof( double ) );
		if ( ndarray ) {
			info = API_SUFFIX(c_dgbtf2_ndarray)( M, N, 1, 1, AB, r, c, 0, PIV, 1, 0 );
		} else {
			info = API_SUFFIX(c_dgbtf2)( LAPACK_ROW_MAJOR, M, N, 1, 1, AB, N, PIV );
		}
		if ( info != expectedInfo ) {
			break;
		}
	}
	elapsed = tic() - t;
	if ( info != expectedInfo || AB[ 0 ] != 999.0 ) {
		elapsed = -1.0;
	}
	for ( i = 0; i < N; i++ ) {
		if ( PIV[ i ] != i+1 ) {
			elapsed = -1.0;
		}
	}
	free( original );
	free( AB );
	free( PIV );
	return elapsed;
}

/**
* Main execution sequence.
*/
int main( void ) {
	const LAPACK_INT sizes[] = { 8, 16 };
	double elapsed;
	int count;
	int passing;
	int i;
	int tall;
	int ndarray;
	int singular;
	int r;

	count = 0;
	passing = 0;
	printf( "TAP version 13\n" );
	for ( i = 0; i < 2; i++ ) {
		for ( tall = 0; tall < 2; tall++ ) {
			for ( ndarray = 0; ndarray < 2; ndarray++ ) {
				for ( singular = 0; singular < 2; singular++ ) {
					for ( r = 0; r < REPEATS; r++ ) {
						count += 1;
						printf( "# c::dgbtf2:N=%d:tall=%d:ndarray=%d:singular=%d\n", (int)sizes[ i ], tall, ndarray, singular );
						elapsed = benchmark( sizes[ i ], tall, ndarray, singular );
						if ( elapsed < 0.0 ) {
							printf( "not ok %d benchmark failed\n", count );
						} else {
							printf( "  ---\n" );
							printf( "  iterations: %d\n", ITERATIONS );
							printf( "  elapsed: %0.9f\n", elapsed );
							printf( "  ...\n" );
							printf( "ok %d benchmark finished\n", count );
							passing += 1;
						}
					}
				}
			}
		}
	}
	printf( "1..%d\n", count );
	printf( "# total %d\n", count );
	printf( "# pass  %d\n", passing );
	if ( passing == count ) {
		printf( "# ok\n" );
		return EXIT_SUCCESS;
	}
	return EXIT_FAILURE;
}
